using System;using ForteMove.Models.Drivers;using ForteMove.Web.Infrastructure;namespace ForteMove.Web.Admin.Drivers{public partial class DriverList:AdminPage{protected void Page_Load(object sender,EventArgs e){if(!IsPostBack){FlashMessage m=FlashMessageStore.Take(Session);if(m!=null){litFlash.Text=Server.HtmlEncode(m.Text);pnlFlash.Visible=true;}Bind();}}protected void btnApply_Click(object sender,EventArgs e){Bind();}private void Bind(){DriverAvailabilityStatus a;CredentialStatus c;var rows=ServiceFactory.CreateDriverService().GetDrivers(new DriverQuery{SearchTerm=txtSearch.Text,AvailabilityStatus=Enum.TryParse(ddlAvailability.SelectedValue,out a)?a:(DriverAvailabilityStatus?)null,CredentialStatus=Enum.TryParse(ddlCredentials.SelectedValue,out c)?c:(CredentialStatus?)null});rptDrivers.DataSource=rows;rptDrivers.DataBind();pnlEmpty.Visible=rows.Count==0;}protected string FormatAvailability(object v){return (DriverAvailabilityStatus)v==DriverAvailabilityStatus.OnLeave?"On leave":v.ToString();}protected string FormatCredential(object v){return (CredentialStatus)v==CredentialStatus.ExpiringSoon?"Expiring soon":v.ToString();}protected string GetAvailabilityCss(object v){return (DriverAvailabilityStatus)v==DriverAvailabilityStatus.Available?"status-badge status-success":"status-badge status-neutral";}protected string GetCredentialCss(object v){return (CredentialStatus)v==CredentialStatus.Expired?"status-badge status-danger":(CredentialStatus)v==CredentialStatus.ExpiringSoon?"status-badge status-warning":"status-badge status-success";}}}
